import { LogicWrapper, MakeLogicType, afterMount, kea, key, path, props } from 'kea'
import { loaders } from 'kea-loaders'

import { dayjs } from 'lib/dayjs'
import { teamLogic } from 'scenes/teamLogic'
import { userLogic } from 'scenes/userLogic'

import { performQuery } from '~/queries/query'
import type { AnyResponseType, DataNode } from '~/queries/schema/schema-general'

import type { ReportChartApi } from 'products/signals/frontend/generated/api.schemas'

export interface ReportChartLogicProps {
    chart: ReportChartApi
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface reportChartLogicValues {
    cachedResults: AnyResponseType | undefined
    cachedResultsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface reportChartLogicActions {
    refreshChart: (_: void) => void
    refreshChartFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    refreshChartSuccess: (
        cachedResults: AnyResponseType,
        payload?: void
    ) => {
        cachedResults: AnyResponseType
        payload?: void
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface reportChartLogicMeta {
    key: string
}

export type reportChartLogicType = MakeLogicType<
    reportChartLogicValues,
    reportChartLogicActions,
    ReportChartLogicProps,
    reportChartLogicMeta
>

export const reportChartLogic: LogicWrapper<reportChartLogicType> = kea<reportChartLogicType>([
    props({} as ReportChartLogicProps),
    key(
        ({ chart }) =>
            `${teamLogic.values.currentTeamId}-${userLogic.values.user?.id}-${chart.chart_id}-${JSON.stringify(chart.query)}-${chart.cached_results_at ?? ''}`
    ),
    path((key) => ['products', 'signals', 'inbox', 'reportChartLogic', key]),
    loaders(({ props, values, cache }) => ({
        cachedResults: [
            props.chart.cached_results as AnyResponseType | undefined,
            {
                refreshChart: async (_: void, breakpoint): Promise<AnyResponseType | undefined> => {
                    const controller = new AbortController()
                    const disposables = cache.disposables
                    disposables.add(
                        () => {
                            const timer = setTimeout(() => controller.abort(), 20_000)
                            return () => {
                                clearTimeout(timer)
                                controller.abort()
                            }
                        },
                        'chartRefresh',
                        { pauseOnPageHidden: false }
                    )
                    try {
                        const query = props.chart.query as { source: DataNode }
                        const result = await performQuery(query.source, { signal: controller.signal }, 'async')
                        await breakpoint()
                        return result
                    } catch {
                        await breakpoint()
                        return values.cachedResults
                    } finally {
                        disposables.dispose('chartRefresh')
                    }
                },
            },
        ],
    })),
    afterMount(({ props, actions }) => {
        const measuredAt = dayjs(props.chart.cached_results_at)
        if (
            props.chart.cached_results &&
            (!props.chart.cached_results_at || !measuredAt.isValid() || dayjs().diff(measuredAt, 'minute') >= 15)
        ) {
            actions.refreshChart()
        }
    }),
])
